package fr.proutlost.worldprep;import fr.proutlost.worldprep.compiler.WorldPrepCompiler;import fr.proutlost.worldprep.pipeline.PassId;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class WorldPrepCompilerTest{@Test void compileIsDeterministicAndBuildRequiresExactIdentity(){var c=new WorldPrepCompiler();var a=c.compile("source","profile","pack",7);var b=c.compile("source","profile","pack",7);assertEquals(a,b);assertTrue(a.passes().contains(PassId.STRUCTURES));assertThrows(IllegalStateException.class,()->c.requireExact(a,"latest"));assertDoesNotThrow(()->c.requireExact(a,a.pipelineId()));}}
